<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash;
class UserManagementController extends Controller { public function index(){return view('admin.users.index',['users'=>User::latest()->get()]);} public function create(){return view('admin.users.create',['user'=>new User]);} public function store(Request $r){$d=$r->validate(['name'=>'required|max:100','email'=>'required|email|max:150|unique:users','password'=>'required|min:8|confirmed','role'=>'required|in:admin,user']);$d['password']=Hash::make($d['password']);User::create($d);return redirect()->route('admin.users.index')->with('success','User dibuat.');} public function edit(User $user){return view('admin.users.create',compact('user'));} public function update(Request $r,User $user){$d=$r->validate(['name'=>'required|max:100','email'=>'required|email|max:150|unique:users,email,'.$user->id,'password'=>'nullable|min:8|confirmed','role'=>'required|in:admin,user']);if(empty($d['password']))unset($d['password']);else $d['password']=Hash::make($d['password']);$user->update($d);return redirect()->route('admin.users.index')->with('success','User diperbarui.');} public function destroy(User $user){abort_if($user->id===auth()->id(),422,'Tidak dapat menghapus akun sendiri.');$user->delete();return back()->with('success','User dihapus.');} }
